// c01EnrichedDoc is the in-memory document state AFTER a first enrichment pass
// (status=ready): sources.tv-parser present + _stages holding a tv-parser:ok entry
// and a tmdb:unavailable entry, exactly as appendStage writes them ([]map[string]any).
func c01EnrichedDoc(relPath string) map[string]any {
	return map[string]any{
		"parsed":  map[string]any{"relative_path": relPath, "stem": "S01E01"},
		"sources": map[string]any{"tv-parser": map[string]any{"title": "done"}},
		"_stages": []map[string]any{
			{"stage": "metadata_source", "plugin_id": "tv-parser", "status": "ok",
				"advanced_to": "enriched", "started_at": "t0", "finished_at": "t1"},
			{"stage": "metadata_source", "plugin_id": "tmdb", "status": "unavailable",
				"advanced_to": "enriched", "started_at": "t2", "finished_at": "t3"},
		},
	}
}

// TestQA_C01_StagesRoundTrip verifies the C-01 fix: decodeDoc normalizes _stages
// back to []map[string]any after a store JSON round-trip, so the unchecked
// assertions in appendStage and attemptedNoWork hold across every re-derive.
func TestQA_C01_StagesRoundTrip(t *testing.T) {
	t.Run("round_trip_preserves_stages_type_and_history", func(t *testing.T) {
		doc := c01EnrichedDoc("Show/S01E01.mkv")
		// in-memory form: appendStage writes []map[string]any.
		if _, ok := doc["_stages"].([]map[string]any); !ok {
			t.Fatalf("precondition: in-memory _stages must be []map[string]any, got %T", doc["_stages"])
		}

		// The store round-trip workItem performs: persistRow marshals, decodeDoc unmarshals.
		rt := roundTripDoc(t, doc)

		// C-01 FIX: after the round-trip, decodeDoc normalizes _stages to []map[string]any
		// (readable by appendStage/attemptedNoWork), NOT the raw []any from encoding/json.
		if _, ok := rt["_stages"].([]map[string]any); !ok {
			t.Fatalf("C-01: round-tripped _stages = %T, want []map[string]any "+
				"(decodeDoc must normalize after the round-trip)", rt["_stages"])
		}

		// C-01 (b): attemptedNoWork READS a round-tripped unavailable stage (true —
		// tmdb ran and produced no work). This is the correct settle-predicate behavior.
		if !attemptedNoWork(rt, "tmdb") {
			t.Fatalf("C-01 (b): attemptedNoWork returned false for a round-tripped " +
				"unavailable stage — it must read prior-pass stages to settle correctly")
		}

		// C-01 (a): appendStage PRESERVES the prior _stages history on a round-tripped doc.
		// The 2 prior entries survive + 1 freshly appended (len 3); tv-parser:ok is retained.
		appendStage(rt, sourceResult{kind: outcomeUnavailable, pluginID: "tmdb",
			startedAt: "t4", finishedAt: "t5"}, "enriched")
		got, _ := rt["_stages"].([]map[string]any)
		if len(got) != 3 {
			t.Fatalf("C-01 (a): after appendStage on round-tripped doc, len(_stages) = %d, "+
				"want 3 (2 prior preserved + 1 appended); stages=%v", len(got), rt["_stages"])
		}
		// the tv-parser:ok audit-history entry SURVIVES the re-derive append.
		if !c01StageHas(rt, "tv-parser", "ok") {
			t.Fatalf("C-01 (a): tv-parser:ok stage lost after appendStage on a round-tripped "+
				"doc — audit history must survive the round-trip; stages=%v", rt["_stages"])
		}
	})

	t.Run("workitem_rederive_preserves_stages_history", func(t *testing.T) {
		// End-to-end: a ready item with persisted _stages is re-derived (the perpetual
		// re-derivation of its unavailable tmdb source, which has no namespace and no
		// ledger row). The worker loads the persisted doc, driveSources re-runs tmdb
		// (unavailable) and appendStage APPENDS — the tv-parser:ok history must survive.
		ctx := context.Background()
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		const itemID = "i_c01"
		putItem(t, s, itemID, libID, statusReady, c01EnrichedDoc("Show/S01E01.mkv"))

		// precondition: the persisted doc carries tv-parser:ok in _stages.
		before := decodeDoc(mustGetDoc(t, s, itemID))
		if !c01StageHas(before, "tv-parser", "ok") {
			t.Fatalf("precondition: persisted doc lost tv-parser:ok before any re-derive (test bug)")
		}

		// tmdb is NOT in the resolver -> outcomeUnavailable (the seeded unloaded SERVER
		// source). tv-parser resolves but hasNamespace -> skipped by driveSources.
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		q.resolve = mapResolver{"tv-parser": &succeedSrc{id: "tv-parser"}}.resolver()
		q.workItem(ctx, itemID) // one re-derive processing pass on the persisted doc

		after := decodeDoc(mustGetDoc(t, s, itemID))
		// C-01 (a) FIXED: the tv-parser:ok audit-history stage SURVIVES the re-derive.
		if !c01StageHas(after, "tv-parser", "ok") {
			t.Fatalf("C-01: tv-parser:ok stage lost across a re-derive workItem — audit "+
				"history must survive the store round-trip; stages=%v", after["_stages"])
		}
		// the freshly-appended tmdb:unavailable stage is present.
		if !c01StageHas(after, "tmdb", "unavailable") {
			t.Fatalf("C-01: tmdb:unavailable stage absent after re-derive; stages=%v", after["_stages"])
		}
		// total stage count: 2 prior (tv-parser:ok, tmdb:unavailable) preserved + 1 fresh
		// tmdb append = 3. The doc is round-tripped again after persist, so count tolerantly
		// across both forms (decodeDoc now normalizes to []map[string]any either way).
		if n := c01StageCount(after); n != 3 {
			t.Fatalf("C-01: post-rederive _stages count = %d, want 3 (2 prior preserved + "+
				"1 fresh append); stages=%v", n, after["_stages"])
		}
	})
}

// roundTripDoc simulates the store persist+load cycle: marshal (persistRow) then
// decodeDoc (workItem's load). Before the C-01 fix this mutated _stages from
// []map[string]any to []any; decodeDoc now normalizes it back to []map[string]any.
func roundTripDoc(t *testing.T, doc map[string]any) map[string]any {
	t.Helper()
	raw, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal doc: %v", err)
	}
	return decodeDoc(raw)
}

// mustGetDoc reads an item's opaque document bytes from the store.
func mustGetDoc(t *testing.T, s *store.Store, id string) []byte {
	t.Helper()
	it, err := s.GetItem(context.Background(), id)
	if err != nil {
		t.Fatalf("GetItem %s: %v", id, err)
	}
	return it.Document
}

// c01StageHas reports whether doc._stages holds an entry for (plugin, status),
// tolerant of both the []map[string]any (in-memory) and []any (round-tripped) forms.
func c01StageHas(doc map[string]any, plugin, status string) bool {
	switch stages := doc["_stages"].(type) {
	case []map[string]any:
		return stageListHas(stages, plugin, status)
	case []any:
		mapped := make([]map[string]any, 0, len(stages))
		for _, e := range stages {
			if m, ok := e.(map[string]any); ok {
				mapped = append(mapped, m)
			}
		}
		return stageListHas(mapped, plugin, status)
	}
	return false
}

// stageListHas scans one homogeneous stage list for an entry matching plugin+status.
func stageListHas(stages []map[string]any, plugin, status string) bool {
	for _, s := range stages {
		pid, _ := s["plugin_id"].(string)
		st, _ := s["status"].(string)
		if pid == plugin && st == status {
			return true
		}
	}
	return false
}

// c01StageCount counts _stages entries tolerantly across both the []map[string]any
// (in-memory) and []any (store-round-tripped) element forms.
func c01StageCount(doc map[string]any) int {
	switch stages := doc["_stages"].(type) {
	case []map[string]any:
		return len(stages)
	case []any:
		return len(stages)
	}
	return 0
}
